export class RetriesExhausted extends Error {
  constructor(attempts, cause) {
    super(`gave up after ${attempts} attempt(s)`);
    this.name = 'RetriesExhausted';
    this.cause = cause;
  }
}

const DEFAULT_BASE_DELAY_MS = 10;
const DEFAULT_MAX_DELAY_MS = 200;

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Call `operation` until it resolves.
 *
 * Retries with exponential backoff between attempts (base delay doubling
 * each time, capped at `maxDelayMs`) so a failing dependency isn't hammered
 * with immediate retries.
 */
export async function retry(operation, options = {}) {
  const maxAttempts = options.maxAttempts ?? 3;
  const baseDelayMs = options.baseDelayMs ?? DEFAULT_BASE_DELAY_MS;
  const maxDelayMs = options.maxDelayMs ?? DEFAULT_MAX_DELAY_MS;
  let last;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await operation(attempt);
    } catch (error) {
      last = error;
      if (attempt < maxAttempts) {
        await delay(Math.min(baseDelayMs * 2 ** (attempt - 1), maxDelayMs));
      }
    }
  }
  throw new RetriesExhausted(maxAttempts, last);
}

