test('backs off exponentially between attempts, capped at maxDelayMs', async () => {
  const timestamps = [];
  await assert.rejects(
    () => retry(
      () => {
        timestamps.push(Date.now());
        return Promise.reject(new Error('always'));
      },
      { maxAttempts: 4, baseDelayMs: 20, maxDelayMs: 50 },
    ),
    RetriesExhausted,
  );

  assert.equal(timestamps.length, 4);
  const gaps = [1, 2, 3].map((i) => timestamps[i] - timestamps[i - 1]);

  assert.ok(gaps[0] >= 15, `gap 1 (${gaps[0]}ms) should be roughly the base delay of 20ms`);
  assert.ok(
    gaps[1] >= gaps[0] * 1.5,
    `gap 2 (${gaps[1]}ms) should be noticeably larger than gap 1 (${gaps[0]}ms)`,
  );
  assert.ok(
    gaps[2] < gaps[1] * 2,
    `gap 3 (${gaps[2]}ms) should be capped near 50ms, not keep doubling from gap 2 (${gaps[1]}ms)`,
  );
});

